+		return "", false, fmt.Errorf("probe symbolic ref %s: %w", refName, ctxErr)
+	}
+	var exitErr *exec.ExitError
+	var stderr []byte
+	if errors.As(err, &exitErr) {
+		stderr = exitErr.Stderr
