		}
		return nil
	}

	return writeFileAtomic(context.Background(), filePath, perm, produce, nil, atomicWriteConfig{
		ops:         defaultAtomicWriteOps(),
		tempPattern: filepath.Base(filePath) + ".*.tmp",
		skipSync:    true,
