+// TryAcquire takes an exclusive advisory lock without waiting.
+// acquired is false when another process holds the lock.
+func TryAcquire(path string) (release func(), acquired bool, err error) {
+	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600) //nolint:gosec // caller is responsible for path validation
+	if err != nil {
+		return nil, false, fmt.Errorf("open flock: %w", err)
+	}
+	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil { //nolint:gosec // file descriptors are non-negative; standard Go pattern for syscall.Flock
+		_ = f.Close()
+		if errors.Is(err, syscall.EWOULDBLOCK) {
+			return nil, false, nil
+		}
+		return nil, false, fmt.Errorf("flock: %w", err)
+	}
+	return func() { _ = f.Close() }, true, nil
+}
