+
+func sessionLockDirectoryIdentity(_ string, info os.FileInfo) (sessionLockIdentity, error) {
+	stat, ok := info.Sys().(*syscall.Stat_t)
+	if !ok {
+		return sessionLockIdentity{}, fmt.Errorf("unexpected directory stat type %T", info.Sys())
+	}
