+func deleteRefLocks(ctx context.Context, ids []string) (deleted, failed []string, err error) {
+	commonDir, err := session.GetGitCommonDir(ctx)
+	if err != nil {
+		return nil, nil, fmt.Errorf("resolve git common dir for ref locks: %w", err)
+	}
+	for _, lockID := range ids {
+		lockPath, pathErr := refLockPath(commonDir, lockID)
+		if pathErr != nil {
+			failed = append(failed, lockID)
+			continue
+		}
+		release, acquired, lockErr := flock.TryAcquire(lockPath)
+		if lockErr != nil || !acquired {
+			failed = append(failed, lockID)
+			continue
+		}
+		removeErr := os.Remove(lockPath)
+		release()
+		if removeErr != nil && !os.IsNotExist(removeErr) {
+			failed = append(failed, lockID)
+			continue
+		}
+		deleted = append(deleted, lockID)
+	}
+	return deleted, failed, nil
+}
+
+func refLockPath(commonDir, lockID string) (string, error) {
+	dirName, fileName := filepath.Dir(lockID), filepath.Base(lockID)
+	if dirName != checkpoint.PersistentRefLockDirName && dirName != checkpoint.ShadowRefLockDirName {
+		return "", fmt.Errorf("invalid ref lock directory %q", dirName)
+	}
+	if lockID != filepath.Join(dirName, fileName) || !strings.HasSuffix(fileName, ".lock") {
+		return "", fmt.Errorf("invalid ref lock ID %q", lockID)
+	}
+	return filepath.Join(commonDir, dirName, fileName), nil
+}
