+		release, acquired, lockErr := flock.TryAcquire(lockPath)
+		if lockErr != nil || !acquired {
+			failed = append(failed, lockID)
+			continue
+		}
+		removeErr := os.Remove(lockPath)
+		release()
+		if removeErr != nil && !os.IsNotExist(removeErr) {
+			failed = append(failed, lockID)
+			continue
+		}
+		deleted = append(deleted, lockID)
+	}
