+	metadata, err := gitrepo.ResolveWorktreeMetadata(worktreeRoot)
+	if err != nil {
+		return "", "", fmt.Errorf("resolve repository metadata: %w", err)
+	}
+	return worktreeRoot, metadata.CommonDir, nil
+}
